<script>
	import { selfAssessments } from '$lib/mipg-new-data.js';
	let search = '';
	$: filtered = selfAssessments.filter((item) => `${item.name} ${item.dimension}`.toLowerCase().includes(search.toLowerCase()));
</script>
<main class="px-4 py-8 sm:px-6 lg:px-10"><div class="mx-auto max-w-7xl space-y-6"><section class="glass-3 rounded-2xl p-6"><p class="text-primary text-xs font-bold uppercase tracking-[0.2em]">MIPG</p><h1 class="mt-2 text-3xl font-bold text-gray-900">Autodiagnósticos</h1><p class="mt-2 text-sm text-gray-600">Evalúa el estado de implementación de las políticas de MIPG.</p><div class="mt-5 max-w-xl"><input bind:value={search} class="block w-full rounded-xl border border-gray-300 bg-white px-3 py-2 text-sm shadow-sm focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/25" placeholder="Buscar instrumento..." aria-label="Buscar instrumentos" /></div></section><section class="glass-3 overflow-x-auto rounded-xl p-4"><table class="min-w-[800px] w-full text-sm"><thead><tr class="border-b border-gray-200 text-left text-xs uppercase tracking-wide text-gray-500"><th class="px-4 py-3">Instrumento</th><th class="px-4 py-3">Dimensión</th><th class="px-4 py-3">Estado</th><th class="px-4 py-3">Avance</th><th class="px-4 py-3">Última actualización</th><th></th></tr></thead><tbody>{#each filtered as item (item.name)}<tr class="border-b border-gray-200/70"><td class="px-4 py-4 font-semibold text-gray-800">{item.name}</td><td class="px-4 py-4 text-gray-600">{item.dimension}</td><td class="px-4 py-4"><span class="rounded-full bg-blue-100 px-2 py-1 text-xs font-semibold text-blue-700">{item.status}</span></td><td class="px-4 py-4"><div class="flex items-center gap-2"><div class="h-2 w-24 rounded-full bg-gray-200"><div class="h-2 rounded-full bg-emerald-500" style={`width: ${item.progress}%`}></div></div><span class="text-xs text-gray-500">{item.progress}%</span></div></td><td class="px-4 py-4 text-gray-500">{item.updated}</td><td class="px-4 py-4 text-right"><button type="button" class="text-primary text-xs font-semibold hover:underline">{item.progress === 100 ? 'Ver resultados' : 'Continuar'}</button></td></tr>{:else}<tr><td colspan="6" class="px-4 py-10 text-center text-gray-500">No hay instrumentos.</td></tr>{/each}</tbody></table></section></div></main>
